#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *a = malloc(sizeof *a);
    if (a == NULL) { return 1; }
    a[0] = 7;
    int *tmp = realloc(a, 2 * sizeof *a);
    if (tmp == NULL) { free(a); return 1; }
    a = tmp;
    a[1] = 9;
    printf("%d %d\n", a[0], a[1]);
    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *a = malloc(4 * sizeof *a);
    if (a == NULL) { return 1; }
    size_t size = 2;
    a[0] = 3; a[1] = 5;
    int sum = 0;
    for (size_t i = 0; i < size; i++) { sum += a[i]; }
    printf("%d\n", sum);
    free(a);
    return 0;
}

